package com.ashokmart.servlet;
import com.ashokmart.model.AuthenticationResult; import com.ashokmart.model.Review; import com.ashokmart.service.*; import com.ashokmart.util.ValidationUtil; import org.slf4j.*; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.IOException;
@WebServlet(urlPatterns={"/reviews/create","/reviews/update","/reviews/delete"}) public final class ReviewServlet extends HttpServlet { private static final Logger LOG=LoggerFactory.getLogger(ReviewServlet.class);
 public void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException,ServletException{req.setCharacterEncoding("UTF-8");AuthenticationResult buyer=ReviewWebSupport.authenticatedBuyer(req,res);if(buyer==null)return;String path=req.getServletPath();long productId=-1;try{productId=path.endsWith("/create")?parse(req.getParameter("productId")):parseOptional(req.getParameter("productId"));var service=ReviewWebSupport.service(ReviewWebSupport.pool(getServletContext()));if(path.endsWith("/create")){service.createReview(buyer.userId(),productId,parseRating(req.getParameter("rating")),req.getParameter("comment"));ReviewWebSupport.flash(req,"reviewSuccess","Your review was published.");redirect(res,req,productId);return;}long reviewId=parse(req.getParameter("reviewId"));Review review=service.getReview(reviewId).orElseThrow(()->new ReviewException("Review not found."));productId=review.getProductId();if(path.endsWith("/update")){service.updateReview(buyer.userId(),reviewId,parseRating(req.getParameter("rating")),req.getParameter("comment"));ReviewWebSupport.flash(req,"reviewSuccess","Your review was updated.");}else if(path.endsWith("/delete")){service.deleteReview(buyer.userId(),reviewId);ReviewWebSupport.flash(req,"reviewSuccess","Your review was deleted.");}else{throw new ReviewException("Unsupported review operation.");}redirect(res,req,productId);}catch(NumberFormatException|ReviewException e){ReviewWebSupport.flash(req,"reviewError",e.getMessage()==null?"Please enter valid review details.":e.getMessage());if(productId>0)redirect(res,req,productId);else res.sendRedirect(req.getContextPath()+"/products");}catch(IllegalStateException e){LOG.error("Review operation failed",e);ReviewWebSupport.flash(req,"reviewError","The review could not be saved. Please try again.");if(productId>0)redirect(res,req,productId);else res.sendRedirect(req.getContextPath()+"/products");}}
 private long parse(String v){try{return ValidationUtil.positiveId(v,"review or product");}catch(IllegalArgumentException e){throw new NumberFormatException(e.getMessage());}} private long parseOptional(String v){if(v==null||v.isBlank())return -1;return parse(v);} private int parseRating(String v){try{return ValidationUtil.rating(v);}catch(IllegalArgumentException e){throw new NumberFormatException(e.getMessage());}} private void redirect(HttpServletResponse res,HttpServletRequest req,long productId)throws IOException{res.sendRedirect(req.getContextPath()+"/product?id="+productId);}
}
